final class MgAiCreditException extends RuntimeException
{
    public function __construct(string $message, private readonly int $httpStatus = 402, private readonly array $details = []) { parent::__construct($message); }
    public function httpStatus(): int { return $this->httpStatus; }
    public function details(): array { return $this->details; }
}

function mg_ai_credit_table_exists(PDO $pdo, string $table): bool
{
    static $cache=[]; $key=spl_object_id($pdo).':'.$table;
    if(array_key_exists($key,$cache))return $cache[$key];
    try{$stmt=$pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$stmt->execute([$table]);return $cache[$key]=((int)$stmt->fetchColumn()>0);}catch(Throwable){return $cache[$key]=false;}
}
function mg_ai_credit_schema_ready(PDO $pdo): bool { return mg_ai_credit_table_exists($pdo,'ai_user_credit_accounts')&&mg_ai_credit_table_exists($pdo,'ai_credit_ledger')&&mg_ai_credit_table_exists($pdo,'ai_usage_events'); }
function mg_ai_credit_provider_key(mixed $value): string { $value=strtolower(trim((string)$value));return preg_match('/^[a-z0-9][a-z0-9._-]{0,79}$/',$value)===1?$value:'anthropic'; }
function mg_ai_credit_nullable_int(mixed $value,int $max=2000000000): ?int { if($value===null||$value==='')return null;$parsed=filter_var($value,FILTER_VALIDATE_INT);return $parsed===false?null:max(0,min($max,(int)$parsed)); }
function mg_ai_credit_int(mixed $value,int $max=2000000000): int { return mg_ai_credit_nullable_int($value,$max)??0; }
function mg_ai_credit_uuid(): string
{
    if(function_exists('mg_public_uuid'))return mg_public_uuid();
    $bytes=random_bytes(16);$bytes[6]=chr((ord($bytes[6])&0x0f)|0x40);$bytes[8]=chr((ord($bytes[8])&0x3f)|0x80);
    return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($bytes),4));
}
function mg_ai_credit_user(PDO $pdo,int $userId): array
{
    $stmt=$pdo->prepare('SELECT id,email,display_name,full_name,status FROM users WHERE id=? LIMIT 1');$stmt->execute([$userId]);$user=$stmt->fetch(PDO::FETCH_ASSOC);
    if(!is_array($user))throw new RuntimeException('User not found.');
    $roles=$pdo->prepare('SELECT r.slug FROM roles r INNER JOIN user_roles ur ON ur.role_id=r.id WHERE ur.user_id=? ORDER BY r.slug');$roles->execute([$userId]);
    $user['roles']=array_values(array_map('strval',$roles->fetchAll(PDO::FETCH_COLUMN)?:[]));return $user;
}
function mg_ai_credit_package_context(PDO $pdo,int $userId): array { return mg_user_package_context($pdo,mg_ai_credit_user($pdo,$userId)); }
function mg_ai_credit_package_policy(array $context): array
{
    $limits=is_array($context['limits']??null)?$context['limits']:[];$hasMonthly=array_key_exists('ai_tokens_monthly_included',$limits);$raw=$hasMonthly?$limits['ai_tokens_monthly_included']:0;
    $unlimited=$hasMonthly&&$raw===null;$monthly=$unlimited?null:mg_ai_credit_int($raw);
    return ['package_id'=>(string)($context['package_id']??'free'),'package_name'=>(string)($context['package_name']??'Free'),'status'=>(string)($context['status']??'free'),'monthly_tokens'=>$monthly,'unlimited'=>$unlimited,
        'daily_limit'=>array_key_exists('ai_tokens_daily_limit',$limits)?mg_ai_credit_nullable_int($limits['ai_tokens_daily_limit']):null,
        'weekly_limit'=>array_key_exists('ai_tokens_weekly_limit',$limits)?mg_ai_credit_nullable_int($limits['ai_tokens_weekly_limit']):null,
        'monthly_limit'=>array_key_exists('ai_tokens_monthly_limit',$limits)?mg_ai_credit_nullable_int($limits['ai_tokens_monthly_limit']):$monthly];
}
function mg_ai_credit_period(array $context): array
{
    $utc=new DateTimeZone('UTC');$subscription=is_array($context['subscription']??null)?$context['subscription']:[];
    try{$start=!empty($subscription['current_period_start'])?new DateTimeImmutable((string)$subscription['current_period_start'],$utc):null;$end=!empty($subscription['current_period_end'])?new DateTimeImmutable((string)$subscription['current_period_end'],$utc):null;}catch(Throwable){$start=null;$end=null;}
    if(!$start||!$end||$end<=$start){$now=new DateTimeImmutable('now',$utc);$start=$now->modify('first day of this month')->setTime(0,0,0);$end=$start->modify('+1 month');}
    return ['start'=>$start,'end'=>$end];
}
function mg_ai_credit_legacy_policy(PDO $pdo,int $userId,string $providerKey): array
{
    if(!mg_ai_credit_table_exists($pdo,'campaign_events'))return [];
    try{$stmt=$pdo->prepare("SELECT event_context_json FROM campaign_events WHERE merchant_user_id=? AND event_type='merchant.ai_user_limits.updated' ORDER BY id DESC LIMIT 1");$stmt->execute([$userId]);$decoded=json_decode((string)($stmt->fetchColumn()?:''),true);if(!is_array($decoded))return [];if(!empty($decoded['provider_key'])&&(string)$decoded['provider_key']!==$providerKey)return [];return $decoded;}catch(Throwable){return [];}
}
function mg_ai_credit_account(PDO $pdo,int $userId,string $providerKey='anthropic'): array
{
    $providerKey=mg_ai_credit_provider_key($providerKey);if(!mg_ai_credit_schema_ready($pdo))return [];$legacy=mg_ai_credit_legacy_policy($pdo,$userId,$providerKey);
    $stmt=$pdo->prepare('INSERT IGNORE INTO ai_user_credit_accounts (user_id,provider_key,enabled,requests_per_hour,requests_per_day,note,created_at,updated_at) VALUES (?,?,?,?,?,?,NOW(),NOW())');
    $stmt->execute([$userId,$providerKey,array_key_exists('enabled',$legacy)?(!empty($legacy['enabled'])?1:0):1,mg_ai_credit_nullable_int($legacy['requests_per_hour']??null,1000000),mg_ai_credit_nullable_int($legacy['requests_per_day']??null,1000000),mb_substr(trim((string)($legacy['note']??'')),0,500)?:null]);
    $stmt=$pdo->prepare('SELECT * FROM ai_user_credit_accounts WHERE user_id=? AND provider_key=? LIMIT 1');$stmt->execute([$userId,$providerKey]);return $stmt->fetch(PDO::FETCH_ASSOC)?:[];
}
function mg_ai_credit_ledger_write(PDO $pdo,array $entry): void
{
    $stmt=$pdo->prepare('INSERT INTO ai_credit_ledger (public_id,user_id,provider_key,provider_id,model_id,entry_type,token_delta,package_token_delta,manual_token_delta,input_tokens,output_tokens,source_type,source_reference,idempotency_key,actor_user_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');
    $stmt->execute([mg_ai_credit_uuid(),(int)$entry['user_id'],mg_ai_credit_provider_key($entry['provider_key']??'anthropic'),$entry['provider_id']??null,$entry['model_id']??null,(string)$entry['entry_type'],(int)($entry['token_delta']??0),(int)($entry['package_token_delta']??0),(int)($entry['manual_token_delta']??0),(int)($entry['input_tokens']??0),(int)($entry['output_tokens']??0),mb_substr(trim((string)($entry['source_type']??'system')),0,80),($ref=mb_substr(trim((string)($entry['source_reference']??'')),0,190))!==''?$ref:null,($key=mb_substr(trim((string)($entry['idempotency_key']??'')),0,190))!==''?$key:null,isset($entry['actor_user_id'])?(int)$entry['actor_user_id']:null,!empty($entry['metadata'])?json_encode($entry['metadata'],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE):null]);
}
function mg_ai_credit_sync_account(PDO $pdo,int $userId,string $providerKey='anthropic'): array
{
    $providerKey=mg_ai_credit_provider_key($providerKey);$row=mg_ai_credit_account($pdo,$userId,$providerKey);if($row===[])return [];$context=mg_ai_credit_package_context($pdo,$userId);$policy=mg_ai_credit_package_policy($context);$period=mg_ai_credit_period($context);$start=$period['start']->format('Y-m-d H:i:s');$end=$period['end']->format('Y-m-d H:i:s');
    $oldAllocated=$row['package_tokens_allocated']===null?null:(int)$row['package_tokens_allocated'];$oldRemaining=$row['package_tokens_remaining']===null?null:(int)$row['package_tokens_remaining'];$newAllocated=$policy['unlimited']?null:(int)$policy['monthly_tokens'];
    $periodChanged=(string)($row['package_id']??'')!==$policy['package_id']||(string)($row['package_period_start']??'')!==$start||(string)($row['package_period_end']??'')!==$end;$allocationChanged=!$periodChanged&&$oldAllocated!==$newAllocated;
    if($periodChanged||$allocationChanged){if($periodChanged)$newRemaining=$newAllocated;elseif($newAllocated===null)$newRemaining=null;else{$used=($oldAllocated!==null&&$oldRemaining!==null)?max(0,$oldAllocated-$oldRemaining):0;$newRemaining=max(0,$newAllocated-$used);} $stmt=$pdo->prepare('UPDATE ai_user_credit_accounts SET package_id=?,package_period_start=?,package_period_end=?,package_tokens_allocated=?,package_tokens_remaining=?,updated_at=NOW() WHERE user_id=? AND provider_key=?');$stmt->execute([$policy['package_id'],$start,$end,$newAllocated,$newRemaining,$userId,$providerKey]);$delta=($newRemaining??0)-($oldRemaining??0);$idempotency=implode(':',['package',$userId,$providerKey,$policy['package_id'],$start,$end,$newAllocated===null?'unlimited':$newAllocated]);try{mg_ai_credit_ledger_write($pdo,['user_id'=>$userId,'provider_key'=>$providerKey,'entry_type'=>$periodChanged?'package_refill':'package_adjustment','token_delta'=>$periodChanged?($newAllocated??0):$delta,'package_token_delta'=>$periodChanged?($newAllocated??0):$delta,'source_type'=>'subscription_package','source_reference'=>$policy['package_id'],'idempotency_key'=>$idempotency,'metadata'=>['period_start'=>$start,'period_end'=>$end,'unlimited'=>$newAllocated===null,'allocation_changed'=>$allocationChanged]]);}catch(PDOException $error){if((string)$error->getCode()!=='23000')throw $error;}$row=mg_ai_credit_account($pdo,$userId,$providerKey);}
