function mg_ai_credit_token_usage(PDO $pdo,int $userId,string $providerKey,DateTimeImmutable $since): int { $stmt=$pdo->prepare("SELECT COALESCE(SUM(ABS(token_delta)),0) FROM ai_credit_ledger WHERE user_id=? AND provider_key=? AND entry_type='usage_debit' AND created_at>=?");$stmt->execute([$userId,$providerKey,$since->format('Y-m-d H:i:s')]);return (int)$stmt->fetchColumn(); }
function mg_ai_credit_request_usage(PDO $pdo,int $userId,string $providerKey,DateTimeImmutable $since): int { try{$stmt=$pdo->prepare("SELECT COALESCE(SUM(request_units),0) FROM ai_usage_events e INNER JOIN ai_providers p ON p.id=e.provider_id WHERE e.user_id=? AND p.provider_key=? AND e.request_status='allowed' AND e.created_at>=?");$stmt->execute([$userId,$providerKey,$since->format('Y-m-d H:i:s')]);return (int)$stmt->fetchColumn();}catch(Throwable){return 0;} }
function mg_ai_credit_effective_limit(mixed $custom,mixed $package): ?int { return $custom!==null?mg_ai_credit_nullable_int($custom):mg_ai_credit_nullable_int($package); }
function mg_ai_credit_snapshot(PDO $pdo,int $userId,string $providerKey='anthropic'): array
{
