utTokens,'source_type'=>$sourceType,'source_reference'=>$sourceReference,'idempotency_key'=>$idempotency,'metadata'=>$metadata+['overage_tokens'=>$overage,'package_unlimited'=>$packageUnlimited]]);if($owns)$pdo->commit();}catch(Throwable $error){if($owns&&$pdo->inTransaction())$pdo->rollBack();throw $error;}return mg_ai_credit_snapshot($pdo,$userId,$providerKey);
